-- MIATA: the complete database (schema + seed data) in one script.
-- Generated by `npm run db:script` from database/migrations and database/seed. Do not edit by hand.
--
-- Run it on a new, empty database (miata_live_db):
--   pgAdmin: create the database, open its Query Tool, open this file, Execute.
--   psql:    psql -h localhost -U postgres -d miata_live_db -f database/miata_live_db.sql
-- It is one transaction: if anything fails (for example the database is not empty), nothing is created.
-- Afterwards copy database/seed/uploads/* into UPLOAD_DIR (the seeded videos and payment proofs), then run
-- `npm run create-admin` for your own admin login.
-- Every seeded account signs in once with Miata-6C75DR9 and must then choose a new password.

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
BEGIN;

CREATE TABLE IF NOT EXISTS schema_migrations (
  name TEXT PRIMARY KEY,
  applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ═══ Migration 001_functions.sql ═══

-- 001 · Functions used by later migrations.
-- Migrations are applied in file-name order by `npm run db:setup` / `npm run migrate` and recorded in
-- schema_migrations. Never edit an applied migration — add a new numbered file instead.

CREATE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

INSERT INTO schema_migrations (name) VALUES ('001_functions.sql');

-- ═══ Migration 002_tables.sql ═══

-- 002 · Tables: columns, primary keys, NOT NULL and defaults.
-- Foreign keys live in 003_relationships.sql, unique/check constraints in 004_constraints.sql,
-- indexes in 005_indexes.sql and triggers in 006_triggers.sql.

CREATE SEQUENCE student_code_seq START 1001;
CREATE SEQUENCE professor_code_seq START 1001;

-- ─── Identity & role profiles ───────────────────────────────────────────

CREATE TABLE users (
  id                    BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email                 TEXT        NOT NULL,
  password_hash         TEXT        NOT NULL,
  full_name             TEXT        NOT NULL,
  phone                 TEXT,
  role                  TEXT        NOT NULL,
  is_active             BOOLEAN     NOT NULL DEFAULT TRUE,
  must_reset_password   BOOLEAN     NOT NULL DEFAULT FALSE,
  password_reset_reason TEXT,
  -- Incremented to invalidate every access token issued before (logout everywhere, deactivation, completion).
  token_version         INTEGER     NOT NULL DEFAULT 0,
  last_login_at         TIMESTAMPTZ,
  created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE student_profiles (
  user_id        BIGINT PRIMARY KEY,
  student_code   TEXT        NOT NULL DEFAULT ('STU' || nextval('student_code_seq')),
  date_of_birth  DATE,
  address        TEXT,
  city           TEXT,
  country        TEXT,
  qualification  TEXT,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE professor_profiles (
  user_id         BIGINT PRIMARY KEY,
  employee_code   TEXT        NOT NULL DEFAULT ('PRF' || nextval('professor_code_seq')),
  department      TEXT,
  specialization  TEXT,
  qualification   TEXT,
  bio             TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE agent_profiles (
  user_id        BIGINT PRIMARY KEY,
  referral_code  TEXT        NOT NULL,
  organization   TEXT,
  city           TEXT,
  country        TEXT,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE agent_referrals (
  id             BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  agent_id       BIGINT      NOT NULL,
  student_id     BIGINT      NOT NULL,
  referral_code  TEXT        NOT NULL,          -- code in effect when the student was attributed
  source         TEXT        NOT NULL,
  created_by     BIGINT,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ─── Authentication tokens (only SHA-256 hashes are stored) ─────────────

CREATE TABLE refresh_tokens (
  id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id      BIGINT      NOT NULL,
  token_hash   TEXT        NOT NULL,
  persistent   BOOLEAN     NOT NULL DEFAULT FALSE,
  expires_at   TIMESTAMPTZ NOT NULL,
  revoked_at   TIMESTAMPTZ,
  replaced_by  BIGINT,
  user_agent   TEXT,
  ip_address   TEXT,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE password_reset_tokens (
  id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id     BIGINT      NOT NULL,
  token_hash  TEXT        NOT NULL,
  purpose     TEXT        NOT NULL,
  expires_at  TIMESTAMPTZ NOT NULL,
  used_at     TIMESTAMPTZ,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ─── Courses & content ──────────────────────────────────────────────────

CREATE TABLE courses (
  id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  code            TEXT        NOT NULL,
  title           TEXT        NOT NULL,
  description     TEXT,
  category        TEXT,
  duration_value  INTEGER,
  duration_unit   TEXT,
  is_active       BOOLEAN     NOT NULL DEFAULT TRUE,
  created_by      BIGINT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE modules (
  id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  course_id    BIGINT      NOT NULL,
  title        TEXT        NOT NULL,
  description  TEXT,
  position     INTEGER     NOT NULL DEFAULT 0,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE lessons (
  id                BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  module_id         BIGINT      NOT NULL,
  title             TEXT        NOT NULL,
  content           TEXT,
  duration_minutes  INTEGER,
  position          INTEGER     NOT NULL DEFAULT 0,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE course_enrolments (
  id            BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  course_id     BIGINT      NOT NULL,
  student_id    BIGINT      NOT NULL,
  status        TEXT        NOT NULL DEFAULT 'active',
  enrolled_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  completed_at  TIMESTAMPTZ,
  enrolled_by   BIGINT,
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE professor_course_assignments (
  id            BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  professor_id  BIGINT      NOT NULL,
  course_id     BIGINT      NOT NULL,
  assigned_by   BIGINT,
  assigned_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE professor_module_assignments (
  id            BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  professor_id  BIGINT      NOT NULL,
  module_id     BIGINT      NOT NULL,
  assigned_by   BIGINT,
  assigned_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ─── Files (metadata only — the bytes live in the upload folder) ────────

CREATE TABLE files (
  id             BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  storage_key    TEXT        NOT NULL,   -- path relative to the upload folder, e.g. videos/2f1c….mp4
  original_name  TEXT        NOT NULL,
  mime_type      TEXT        NOT NULL,
  size_bytes     BIGINT      NOT NULL,
  kind           TEXT        NOT NULL,
  uploaded_by    BIGINT,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE videos (
  id                BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  course_id         BIGINT      NOT NULL,
  module_id         BIGINT,
  lesson_id         BIGINT,
  file_id           BIGINT      NOT NULL,
  title             TEXT        NOT NULL,
  description       TEXT,
  duration_seconds  INTEGER     NOT NULL,
  position          INTEGER     NOT NULL DEFAULT 0,
  is_published      BOOLEAN     NOT NULL DEFAULT FALSE,
  is_required       BOOLEAN     NOT NULL DEFAULT TRUE,
  published_at      TIMESTAMPTZ,
  uploaded_by       BIGINT,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Watch time is credited from playback heartbeats, capped by real elapsed time (progress.service.js).
CREATE TABLE video_progress (
  id                 BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  video_id           BIGINT        NOT NULL,
  student_id         BIGINT        NOT NULL,
  watched_seconds    NUMERIC(10,2) NOT NULL DEFAULT 0,
  last_position      NUMERIC(10,2) NOT NULL DEFAULT 0,
  last_heartbeat_at  TIMESTAMPTZ,
  completed_at       TIMESTAMPTZ,
  created_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
  updated_at         TIMESTAMPTZ   NOT NULL DEFAULT now()
);

-- ─── Assignments, submissions, reviews ──────────────────────────────────

CREATE TABLE assignments (
  id                  BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  course_id           BIGINT      NOT NULL,
  module_id           BIGINT,
  title               TEXT        NOT NULL,
  instructions        TEXT,
  due_at              TIMESTAMPTZ,
  is_required         BOOLEAN     NOT NULL DEFAULT TRUE,
  is_published        BOOLEAN     NOT NULL DEFAULT TRUE,
  attachment_file_id  BIGINT,
  created_by          BIGINT,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE assignment_submissions (
  id             BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  assignment_id  BIGINT      NOT NULL,
  student_id     BIGINT      NOT NULL,
  attempt_no     INTEGER     NOT NULL,
  file_id        BIGINT      NOT NULL,
  notes          TEXT,
  status         TEXT        NOT NULL DEFAULT 'submitted',
  submitted_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  reviewed_at    TIMESTAMPTZ,
  reviewed_by    BIGINT,
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE assignment_reviews (
  id             BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  submission_id  BIGINT      NOT NULL,
  professor_id   BIGINT      NOT NULL,
  decision       TEXT        NOT NULL,
  feedback       TEXT,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE submission_comments (
  id             BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  submission_id  BIGINT      NOT NULL,
  author_id      BIGINT      NOT NULL,
  body           TEXT        NOT NULL,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ─── Enquiries ──────────────────────────────────────────────────────────

CREATE TABLE enquiries (
  id               BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name             TEXT        NOT NULL,
  email            TEXT        NOT NULL,
  phone            TEXT,
  subject          TEXT,
  message          TEXT        NOT NULL,
  course_interest  TEXT,
  source           TEXT        NOT NULL DEFAULT 'website',
  status           TEXT        NOT NULL DEFAULT 'new',
  follow_up_on     DATE,
  email_status     TEXT        NOT NULL DEFAULT 'pending',
  email_error      TEXT,
  ip_address       TEXT,
  created_by       BIGINT,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE enquiry_notes (
  id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  enquiry_id  BIGINT      NOT NULL,
  author_id   BIGINT,
  note        TEXT        NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ─── Notifications, activity, settings ─────────────────────────────────

CREATE TABLE notifications (
  id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id     BIGINT      NOT NULL,
  type        TEXT        NOT NULL,
  title       TEXT        NOT NULL,
  body        TEXT,
  link        TEXT,
  read_at     TIMESTAMPTZ,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE activity_logs (
  id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  actor_id     BIGINT,
  action       TEXT        NOT NULL,     -- e.g. course.created, submission.completed, course.completed
  entity_type  TEXT,
  entity_id    BIGINT,
  description  TEXT        NOT NULL,
  metadata     JSONB       NOT NULL DEFAULT '{}'::jsonb,
  ip_address   TEXT,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE app_settings (
  key         TEXT PRIMARY KEY,
  value       JSONB       NOT NULL,
  updated_by  BIGINT,
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

INSERT INTO schema_migrations (name) VALUES ('002_tables.sql');

-- ═══ Migration 003_relationships.sql ═══

-- 003 · Relationships (foreign keys).
-- ON DELETE rules: CASCADE for data owned by a parent (profiles, tokens, modules → lessons),
-- RESTRICT for history that must survive (enrolments, submissions, reviews), SET NULL for "who did it" columns.

-- Role profiles: one per user
ALTER TABLE student_profiles   ADD CONSTRAINT fk_student_profiles_user   FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE;
ALTER TABLE professor_profiles ADD CONSTRAINT fk_professor_profiles_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE;
ALTER TABLE agent_profiles     ADD CONSTRAINT fk_agent_profiles_user     FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE;

-- Referrals: agent 1:N students
ALTER TABLE agent_referrals ADD CONSTRAINT fk_agent_referrals_agent      FOREIGN KEY (agent_id)   REFERENCES users (id) ON DELETE RESTRICT;
ALTER TABLE agent_referrals ADD CONSTRAINT fk_agent_referrals_student    FOREIGN KEY (student_id) REFERENCES users (id) ON DELETE CASCADE;
ALTER TABLE agent_referrals ADD CONSTRAINT fk_agent_referrals_created_by FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL;

-- Tokens
ALTER TABLE refresh_tokens        ADD CONSTRAINT fk_refresh_tokens_user        FOREIGN KEY (user_id)     REFERENCES users (id)          ON DELETE CASCADE;
ALTER TABLE refresh_tokens        ADD CONSTRAINT fk_refresh_tokens_replaced_by FOREIGN KEY (replaced_by) REFERENCES refresh_tokens (id) ON DELETE SET NULL;
ALTER TABLE password_reset_tokens ADD CONSTRAINT fk_password_reset_tokens_user FOREIGN KEY (user_id)     REFERENCES users (id)          ON DELETE CASCADE;

-- Courses → modules → lessons
ALTER TABLE courses ADD CONSTRAINT fk_courses_created_by FOREIGN KEY (created_by) REFERENCES users (id)   ON DELETE SET NULL;
ALTER TABLE modules ADD CONSTRAINT fk_modules_course     FOREIGN KEY (course_id)  REFERENCES courses (id) ON DELETE CASCADE;
ALTER TABLE lessons ADD CONSTRAINT fk_lessons_module     FOREIGN KEY (module_id)  REFERENCES modules (id) ON DELETE CASCADE;

-- Enrolments: courses N:M students
ALTER TABLE course_enrolments ADD CONSTRAINT fk_course_enrolments_course      FOREIGN KEY (course_id)   REFERENCES courses (id) ON DELETE RESTRICT;
ALTER TABLE course_enrolments ADD CONSTRAINT fk_course_enrolments_student     FOREIGN KEY (student_id)  REFERENCES users (id)   ON DELETE RESTRICT;
ALTER TABLE course_enrolments ADD CONSTRAINT fk_course_enrolments_enrolled_by FOREIGN KEY (enrolled_by) REFERENCES users (id)   ON DELETE SET NULL;

-- Teaching: courses/modules N:M professors
ALTER TABLE professor_course_assignments ADD CONSTRAINT fk_pca_professor   FOREIGN KEY (professor_id) REFERENCES users (id)   ON DELETE CASCADE;
ALTER TABLE professor_course_assignments ADD CONSTRAINT fk_pca_course      FOREIGN KEY (course_id)    REFERENCES courses (id) ON DELETE CASCADE;
ALTER TABLE professor_course_assignments ADD CONSTRAINT fk_pca_assigned_by FOREIGN KEY (assigned_by)  REFERENCES users (id)   ON DELETE SET NULL;
ALTER TABLE professor_module_assignments ADD CONSTRAINT fk_pma_professor   FOREIGN KEY (professor_id) REFERENCES users (id)   ON DELETE CASCADE;
ALTER TABLE professor_module_assignments ADD CONSTRAINT fk_pma_module      FOREIGN KEY (module_id)    REFERENCES modules (id) ON DELETE CASCADE;
ALTER TABLE professor_module_assignments ADD CONSTRAINT fk_pma_assigned_by FOREIGN KEY (assigned_by)  REFERENCES users (id)   ON DELETE SET NULL;

-- Files and videos
ALTER TABLE files  ADD CONSTRAINT fk_files_uploaded_by  FOREIGN KEY (uploaded_by) REFERENCES users (id)   ON DELETE SET NULL;
ALTER TABLE videos ADD CONSTRAINT fk_videos_course      FOREIGN KEY (course_id)   REFERENCES courses (id) ON DELETE RESTRICT;
ALTER TABLE videos ADD CONSTRAINT fk_videos_module      FOREIGN KEY (module_id)   REFERENCES modules (id) ON DELETE SET NULL;
ALTER TABLE videos ADD CONSTRAINT fk_videos_lesson      FOREIGN KEY (lesson_id)   REFERENCES lessons (id) ON DELETE SET NULL;
ALTER TABLE videos ADD CONSTRAINT fk_videos_file        FOREIGN KEY (file_id)     REFERENCES files (id)   ON DELETE RESTRICT;
ALTER TABLE videos ADD CONSTRAINT fk_videos_uploaded_by FOREIGN KEY (uploaded_by) REFERENCES users (id)   ON DELETE SET NULL;
ALTER TABLE video_progress ADD CONSTRAINT fk_video_progress_video   FOREIGN KEY (video_id)   REFERENCES videos (id) ON DELETE CASCADE;
ALTER TABLE video_progress ADD CONSTRAINT fk_video_progress_student FOREIGN KEY (student_id) REFERENCES users (id)  ON DELETE CASCADE;

-- Assignments → submissions → reviews / comments
ALTER TABLE assignments ADD CONSTRAINT fk_assignments_course     FOREIGN KEY (course_id)          REFERENCES courses (id) ON DELETE RESTRICT;
ALTER TABLE assignments ADD CONSTRAINT fk_assignments_module     FOREIGN KEY (module_id)          REFERENCES modules (id) ON DELETE SET NULL;
ALTER TABLE assignments ADD CONSTRAINT fk_assignments_attachment FOREIGN KEY (attachment_file_id) REFERENCES files (id)   ON DELETE SET NULL;
ALTER TABLE assignments ADD CONSTRAINT fk_assignments_created_by FOREIGN KEY (created_by)         REFERENCES users (id)   ON DELETE SET NULL;
ALTER TABLE assignment_submissions ADD CONSTRAINT fk_submissions_assignment  FOREIGN KEY (assignment_id) REFERENCES assignments (id) ON DELETE RESTRICT;
ALTER TABLE assignment_submissions ADD CONSTRAINT fk_submissions_student     FOREIGN KEY (student_id)    REFERENCES users (id)       ON DELETE RESTRICT;
ALTER TABLE assignment_submissions ADD CONSTRAINT fk_submissions_file        FOREIGN KEY (file_id)       REFERENCES files (id)       ON DELETE RESTRICT;
ALTER TABLE assignment_submissions ADD CONSTRAINT fk_submissions_reviewed_by FOREIGN KEY (reviewed_by)   REFERENCES users (id)       ON DELETE SET NULL;
ALTER TABLE assignment_reviews  ADD CONSTRAINT fk_reviews_submission  FOREIGN KEY (submission_id) REFERENCES assignment_submissions (id) ON DELETE CASCADE;
ALTER TABLE assignment_reviews  ADD CONSTRAINT fk_reviews_professor   FOREIGN KEY (professor_id)  REFERENCES users (id)                  ON DELETE RESTRICT;
ALTER TABLE submission_comments ADD CONSTRAINT fk_comments_submission FOREIGN KEY (submission_id) REFERENCES assignment_submissions (id) ON DELETE CASCADE;
ALTER TABLE submission_comments ADD CONSTRAINT fk_comments_author     FOREIGN KEY (author_id)     REFERENCES users (id)                  ON DELETE RESTRICT;

-- Enquiries
ALTER TABLE enquiries     ADD CONSTRAINT fk_enquiries_created_by FOREIGN KEY (created_by) REFERENCES users (id)     ON DELETE SET NULL;
ALTER TABLE enquiry_notes ADD CONSTRAINT fk_enquiry_notes_enquiry FOREIGN KEY (enquiry_id) REFERENCES enquiries (id) ON DELETE CASCADE;
ALTER TABLE enquiry_notes ADD CONSTRAINT fk_enquiry_notes_author  FOREIGN KEY (author_id)  REFERENCES users (id)     ON DELETE SET NULL;

-- Notifications, activity, settings
ALTER TABLE notifications ADD CONSTRAINT fk_notifications_user      FOREIGN KEY (user_id)    REFERENCES users (id) ON DELETE CASCADE;
ALTER TABLE activity_logs ADD CONSTRAINT fk_activity_logs_actor     FOREIGN KEY (actor_id)   REFERENCES users (id) ON DELETE SET NULL;
ALTER TABLE app_settings  ADD CONSTRAINT fk_app_settings_updated_by FOREIGN KEY (updated_by) REFERENCES users (id) ON DELETE SET NULL;

INSERT INTO schema_migrations (name) VALUES ('003_relationships.sql');

-- ═══ Migration 004_constraints.sql ═══

-- 004 · Constraints: uniqueness and allowed values (business rules enforced by the database itself).

-- Users
ALTER TABLE users ADD CONSTRAINT ck_users_role CHECK (role IN ('admin', 'agent', 'professor', 'student'));
ALTER TABLE users ADD CONSTRAINT ck_users_email_lowercase CHECK (email = lower(email));
ALTER TABLE users ADD CONSTRAINT ck_users_reset_reason
  CHECK (password_reset_reason IN ('account_created', 'course_completed', 'admin_request'));

-- Role profiles
ALTER TABLE student_profiles   ADD CONSTRAINT uq_student_profiles_code   UNIQUE (student_code);
ALTER TABLE professor_profiles ADD CONSTRAINT uq_professor_profiles_code UNIQUE (employee_code);
ALTER TABLE agent_profiles     ADD CONSTRAINT uq_agent_profiles_referral_code UNIQUE (referral_code);
ALTER TABLE agent_profiles     ADD CONSTRAINT ck_agent_profiles_referral_code CHECK (referral_code ~ '^[A-Z0-9]{6,16}$');

-- Referrals: one attribution per student (prevents duplicate referral attribution)
ALTER TABLE agent_referrals ADD CONSTRAINT uq_agent_referrals_student UNIQUE (student_id);
ALTER TABLE agent_referrals ADD CONSTRAINT ck_agent_referrals_source CHECK (source IN ('link', 'admin'));
ALTER TABLE agent_referrals ADD CONSTRAINT ck_agent_referrals_not_self CHECK (agent_id <> student_id);

-- Tokens
ALTER TABLE refresh_tokens        ADD CONSTRAINT uq_refresh_tokens_hash UNIQUE (token_hash);
ALTER TABLE password_reset_tokens ADD CONSTRAINT uq_password_reset_tokens_hash UNIQUE (token_hash);
ALTER TABLE password_reset_tokens ADD CONSTRAINT ck_password_reset_tokens_purpose CHECK (purpose IN ('reset', 'forced'));

-- Courses & content
ALTER TABLE courses ADD CONSTRAINT uq_courses_code UNIQUE (code);
ALTER TABLE courses ADD CONSTRAINT ck_courses_duration_value CHECK (duration_value > 0);
ALTER TABLE courses ADD CONSTRAINT ck_courses_duration_unit CHECK (duration_unit IN ('days', 'weeks', 'months', 'years'));
ALTER TABLE courses ADD CONSTRAINT ck_courses_duration_pair CHECK ((duration_value IS NULL) = (duration_unit IS NULL));
ALTER TABLE lessons ADD CONSTRAINT ck_lessons_duration CHECK (duration_minutes > 0);

-- Enrolments: a student enrols in a course once; "completed" always carries its timestamp
ALTER TABLE course_enrolments ADD CONSTRAINT uq_course_enrolments UNIQUE (course_id, student_id);
ALTER TABLE course_enrolments ADD CONSTRAINT ck_course_enrolments_status CHECK (status IN ('active', 'suspended', 'completed'));
ALTER TABLE course_enrolments ADD CONSTRAINT ck_course_enrolments_completed CHECK ((status = 'completed') = (completed_at IS NOT NULL));

-- Teaching assignments
ALTER TABLE professor_course_assignments ADD CONSTRAINT uq_professor_course UNIQUE (professor_id, course_id);
ALTER TABLE professor_module_assignments ADD CONSTRAINT uq_professor_module UNIQUE (professor_id, module_id);

-- Files and videos
ALTER TABLE files  ADD CONSTRAINT uq_files_storage_key UNIQUE (storage_key);
ALTER TABLE files  ADD CONSTRAINT ck_files_size CHECK (size_bytes >= 0);
ALTER TABLE files  ADD CONSTRAINT ck_files_kind CHECK (kind IN ('video', 'attachment', 'submission'));
ALTER TABLE videos ADD CONSTRAINT ck_videos_duration CHECK (duration_seconds > 0);
ALTER TABLE video_progress ADD CONSTRAINT uq_video_progress UNIQUE (video_id, student_id);
ALTER TABLE video_progress ADD CONSTRAINT ck_video_progress_watched CHECK (watched_seconds >= 0);

-- Submissions & reviews
ALTER TABLE assignment_submissions ADD CONSTRAINT uq_submission_attempt UNIQUE (assignment_id, student_id, attempt_no);
ALTER TABLE assignment_submissions ADD CONSTRAINT ck_submissions_attempt CHECK (attempt_no >= 1);
ALTER TABLE assignment_submissions ADD CONSTRAINT ck_submissions_status CHECK (status IN ('submitted', 'in_review', 'rework', 'completed'));
ALTER TABLE assignment_reviews ADD CONSTRAINT ck_reviews_decision CHECK (decision IN ('completed', 'rework'));
ALTER TABLE assignment_reviews ADD CONSTRAINT ck_reviews_rework_feedback CHECK (decision <> 'rework' OR length(trim(coalesce(feedback, ''))) > 0);
ALTER TABLE submission_comments ADD CONSTRAINT ck_comments_body CHECK (length(body) BETWEEN 1 AND 5000);

-- Enquiries
ALTER TABLE enquiries ADD CONSTRAINT ck_enquiries_source CHECK (source IN ('website', 'admin'));
ALTER TABLE enquiries ADD CONSTRAINT ck_enquiries_status CHECK (status IN ('new', 'contacted', 'follow_up', 'converted', 'closed'));
ALTER TABLE enquiries ADD CONSTRAINT ck_enquiries_email_status CHECK (email_status IN ('pending', 'sent', 'failed', 'skipped'));
ALTER TABLE enquiry_notes ADD CONSTRAINT ck_enquiry_notes_note CHECK (length(note) BETWEEN 1 AND 5000);

INSERT INTO schema_migrations (name) VALUES ('004_constraints.sql');

-- ═══ Migration 005_indexes.sql ═══

-- 005 · Indexes for the queries the API runs (lists, filters, scope checks) and partial unique indexes.

CREATE UNIQUE INDEX users_email_key ON users (email);
CREATE INDEX users_role_idx ON users (role, is_active);

CREATE INDEX agent_referrals_agent_idx ON agent_referrals (agent_id, created_at DESC);

CREATE INDEX refresh_tokens_user_idx ON refresh_tokens (user_id) WHERE revoked_at IS NULL;
CREATE INDEX password_reset_tokens_user_idx ON password_reset_tokens (user_id) WHERE used_at IS NULL;

CREATE INDEX modules_course_idx ON modules (course_id, position);
CREATE INDEX lessons_module_idx ON lessons (module_id, position);
CREATE INDEX course_enrolments_student_idx ON course_enrolments (student_id);
CREATE INDEX professor_course_assignments_course_idx ON professor_course_assignments (course_id);
CREATE INDEX professor_module_assignments_module_idx ON professor_module_assignments (module_id);

CREATE INDEX videos_course_idx ON videos (course_id, is_published);
CREATE INDEX videos_module_idx ON videos (module_id);
CREATE INDEX video_progress_student_idx ON video_progress (student_id);

CREATE INDEX assignments_course_idx ON assignments (course_id, is_published);
