-- ─── Indexes ────────────────────────────────────────────────────────────

CREATE INDEX batches_active_idx ON batches (is_active, start_date DESC);
CREATE INDEX batch_courses_course_idx ON batch_courses (course_id);
CREATE INDEX batch_students_batch_idx ON batch_students (batch_id);
