{"id":1,"code":"PGDU","title":"PG Diploma in Ultrasound","description":"One-year blended ultrasound program with international clinical training and an ARDMS pathway: six months of theory, three months of clinical training and a paid internship.","category":"Diploma","duration_value":12,"duration_unit":"months","is_active":true,"created_by":1,"created_at":"2026-10-13T21:00:12.236128+05:30","updated_at":"2026-10-13T21:00:12.236128+05:30","fee_amount":36000,"academic_year":null,"start_date":null,"end_date":null,"schedule_notes":null},
